        public string input_sn
        {

            set
            {
                this.golb_var_default["input_sn"] = value;
                if (setup_ini_data["setport"]["Festoolport"] != null) // for festool_mmu
                {
                    if (setup_ini_data["setport"]["Festool_contol_add"] == null)
                    {
                        if (value.ToUpper().IndexOf("SN") <= 0) { throw new Exception("SN error"); }

                        string sn = value.Substring(value.ToUpper().IndexOf("SN") + 2, 8);

                        Regex regex = new Regex(@"SN(\d{8})");
                        System.Text.RegularExpressions.Match match = regex.Match(value);

                        if (match.Success)
                        {
                            festoolcom.sn_by_scaner = uint.Parse(match.Groups[1].Value);
                        }
                        else
                        {

                            throw new Exception("SN ERROR");
                        }
                    }
                    else
                    {

                        //  if (value.ToUpper().IndexOf("SN") <= 0) { throw new Exception("SN error"); }

                        //  string sn = value.Substring(value.ToUpper().IndexOf("SN") + 2, 8);

                        Regex regex = new Regex(@"SN(\d{8})");
                        System.Text.RegularExpressions.Match match = regex.Match(value);

                        if (match.Success)
                        {
                            festoolcom.sn_by_scaner = uint.Parse(match.Groups[1].Value);
                        }
                        else
                        {

                            throw new Exception("SN ERROR");
                        }



                    }

                }

                this.trf = value;
                if (value.IndexOf(" ") > 0) { this.production_serial_number = value.Split(" ".ToArray())[0]; }
                else { this.production_serial_number = value; }
                // if (value.IndexOf("WP") >= 0) { this.production_serial_number = value.Substring(value.Length - 7, 7); }


            }
            get
            {

                return this.trf;
            }

        }
