                    hipot_9310 = new hipot_tonghui9310(temp_port, temp_port_baudrate);
                    Task.Factory.StartNew(() =>
                    {

                        try
                        {

                            int setter_cout = 0;
                            if (setup_ini_data["TH_9310_HIPOT"] != null)
                            {

                                setter_cout = setup_ini_data["TH_9310_HIPOT"].Count;

                            }
                            else
                            {

                                throw new Exception("setup.ini error!!");

                            }

                            int cp, m = 0;
                            do
                            {
                                hipot_9310.WriteLine("FUNC:SOUR:STEP ?");
                                string p = hipot_9310.ReadLine();
                                cp = int.Parse(p);
                                if (cp == setter_cout) break;
                                if (cp > setter_cout) hipot_9310.WriteLine("FUNC:SOUR:STEP DEL");
                                if (cp < setter_cout) hipot_9310.WriteLine("FUNC:SOUR:STEP INS");
                            } while (m++ < 20);


                            foreach (var vpm in setup_ini_data["TH_9310_HIPOT"])
                            {


                                hipot_9310.WriteLine(vpm.Value);

                            }

                            hipot_9310.WriteLine("MMEM:STOR:STAT 1,\"DN_PROJ\"");

                        }
