        string run_no_return(string a, string b, out string c, string d = "") {


            // string str_exe = @"E:\360MoveData\Users\HP\Desktop\toc_board\customer_user_fw_program.CMD";
       
           

            string exePath = d.Split(';')[0];
            string arguments = "";          // 传递给目标程序的参数
            string workingDir = Path.GetDirectoryName(exePath);

            string f_rsu_str = "";
            if (!Path.IsPathRooted(d.Split(';')[1]))
            {

                f_rsu_str = workingDir + "\\" + d.Split(';')[1];


            }
            else {
                
                f_rsu_str = d.Split(';')[1];


            }
            if (File.Exists(f_rsu_str)) File.Delete(f_rsu_str);
            ProcessStartInfo startInfo = new ProcessStartInfo
            {
                FileName = exePath,          // 要启动的可执行文件路径
                Arguments = arguments,                // 可选：命令行参数
                WorkingDirectory = workingDir,
                UseShellExecute = true,                // 必须为 false 才能重定向或隐藏窗口
                CreateNoWindow = false,                  // 不创建窗口（后台运行）
                RedirectStandardOutput = false,         // 如果不需要读取输出，可设为 false
                RedirectStandardError = false
            };

            try
            {
                using (Process process = Process.Start(startInfo))
                {
                    // 如果需要等待程序结束，可调用 process.WaitForExit();
                    // 否则，程序将在后台运行，当前进程继续执行

                }
            }
            catch (Exception ex)
            {

            }


            utility_func.callbackdebuginfo("running :"+ exePath);
           

            System.Threading.Thread.Sleep(500);
            string rsu_str = "";
            for (int i=0;i<int.Parse(d.Split(';')[2]);i++ )
            {
                string ptxt = "";
                try
                {
                   
                    ptxt = File.ReadAllText(f_rsu_str);

                }
                catch { System.Threading.Thread.Sleep(500); }

                utility_func.callbackdebuginfo(ptxt);
                if (ptxt.IndexOf(a.Trim()) >= 0)
                {

                    utility_func.callbackdebuginfo(ptxt);
                    c = "pass";
                    return "pass";
                  

                }

                if (ptxt.ToLower().IndexOf("fail") >= 0)
                {

                    utility_func.callbackdebuginfo(ptxt);
                    c = "fail";
                    return "fail";


                }


                System.Threading.Thread.Sleep(500);
            }


           
            c = "fail";
            return "fail";


        }
        private string run_console_read_StandardOutput(string a, string b, out string c, string d)
        {

            c = "fail";
            if (d == "") d = @"a.bat;Lost = 0";
            try
            {
                if (d.Split(';').Length < 2) { c = "pram error"; return "fail"; }
                if (d.Split(';').Length == 3)
                {
                    var rsu = mylib.utility_func.run_console_pip(d.Split(';')[0],EndStr: d.Split(';')[2]);
                    c = rsu.ToString();
                    System.Text.RegularExpressions.Match match = Regex.Match(c, d.Split(';')[1]);
                    if (match.Success) {
                        c = match.Value;
                        return "pass";
                    
                    }

                    c = "fail";
                    return "fail";
                }else if(d.Split(';').Length == 4) {

                    var rsu = mylib.utility_func.run_console_pip(d.Split(';')[0], EndStr: d.Split(';')[2], timeout: int.Parse(d.Split(';')[3]));
                    c = rsu.ToString();
                    System.Text.RegularExpressions.Match match = Regex.Match(c, d.Split(';')[1]);
                    if (match.Success)
                    {
                        c = match.Value;
                        return "pass";

                    }

                    c = "fail";
                    return "fail";




                }
                else {

                    var rsu = mylib.utility_func.run_console_pip(d.Split(';')[0], 10000);
                    c = rsu.ToString();
                    string f_str = d.Split(';')[1];
                    if (rsu.ToString().IndexOf(f_str) >= 0)
                    {
                        c = "pass";
                        return "pass";

                    }
                    else
                    {
                        c = "ping out fial";
                        return "fail";
                    }
                }
                return "fail";
            }
            catch (Exception e)
            {
                mylib.utility_func.callbackdebuginfo(e.ToString());
                c = "error";
                return "fail";

            }
            return "fail";

        }
