            c = "fail";
            bIOFI_PROD.dosometing = null;
            switch (test_param_str_group[0])
            {
                case "SPLIT_PROD_UUID_PASSWORD":
                    {
                        //string t = messbox_from(@"^[0-9|a-z|A-Z]{8,32}$", "Input PROD_UUID", $"Please input PROD_UUID");

                        string[] strtmp = this.trf.Trim().Split("-".ToArray());
                        if (strtmp.Length != 2) { c = "QRCODE_FORMAT_ERROR"; return "fail"; }
                        BIOFI_PROD_UUID = strtmp[0].Trim();
                        BIOFI_PROD_PASSWORD = strtmp[1].Trim();

                        c = this.trf.Trim();

                        SendMessage(ptrWnd, WM_CHANGE_TEXT_BOX1, IntPtr.Zero, BIOFI_PROD_UUID);

                        return "pass";
                    }
                    break;

                case "Program_Unique_ID_Number":
                    {
                        //     BIOFI_PROD_UUID = "ABCDEFGH";
                        //   BIOFI_PROD_PASSWORD = "12345678";
                        if (BIOFI_PROD_UUID.Length < 8 || BIOFI_PROD_PASSWORD.Length < 8)
                        {

                            c = "UUID or password length error";
                            return "fail";
                        };
                        bool fanzhuan = false;
                        byte[] BIOFI_PROD_UUID_bytes = System.Text.Encoding.ASCII.GetBytes((fanzhuan == false) ? BIOFI_PROD_UUID.Trim() : new string(BIOFI_PROD_UUID.Trim().Reverse().ToArray()));
                        byte[] BIOFI_PROD_PASSWORD_bytes = System.Text.Encoding.ASCII.GetBytes((fanzhuan == false) ? BIOFI_PROD_PASSWORD.Trim() : new string(BIOFI_PROD_PASSWORD.Trim().Reverse().ToArray()));
                        int uuidlen = BIOFI_PROD_UUID_bytes.Length;
                        int passwordlen = BIOFI_PROD_PASSWORD_bytes.Length;
                        byte[] send_byte_groups = new byte[uuidlen + passwordlen + 2];
                        send_byte_groups[0] = (byte)uuidlen;
                        send_byte_groups[uuidlen + 1] = (byte)passwordlen;
                        Array.Copy(BIOFI_PROD_UUID_bytes, 0, send_byte_groups, 1, uuidlen);
                        Array.Copy(BIOFI_PROD_PASSWORD_bytes, 0, send_byte_groups, uuidlen + 2, passwordlen);
                        string t = "";
                        if (bIOFI_PROD.send_command(0x20, send_byte_groups, out t) == 1)
                        {

                            c = t;
                            if (t.StartsWith("20"))
                            {
                                return "pass";
                            }
                            else
                            {


                                return "fail";
                            }


                        }
                        else
                        {

                            c = "fail";
                            return "fail";

                        };

                    }
                    break;

                case "RESET_COMMAND":
                    {
                        string t = "";
                        if (bIOFI_PROD.send_command(0x21, new byte[] { }, out t) == 1)
                        {

                            c = t;
                            if (t.StartsWith("21") && t.Length % 2 == 0)
                            {

                                return "pass";
                            }
                            else
                            {
                                return "fail";

                            }

                        }
