        string pycom_script_run(string a, string b, out string c, string d = "")
        {

            if (d == null) d = "test.py;30;\\d+";

            string[] temp = d.Split(";".ToArray());

            string rst = pycom_obj.pycom_script_run(temp[0], int.Parse(temp[1]), temp[2]).Trim();
            utility_func.callbackdebuginfo(rst + "");

            string[] limitstr_group = a.Split(':');
            string routing = "";
            if (limitstr_group.Length == 2)
            {
                routing = limitstr_group[0];

                if (!routing.StartsWith("dm"))
                {
                    a = limitstr_group[1];
                    b = b.Split(':')[1];

                }
            }
            c = rst.Trim();
            if (rst == "null") { return "fail"; }
            switch (routing)
            {
                case "dm":
                    {

                        string[] snr_rssi_h = a.Split(':')[1].Split('|');
                        string[] snr_rssi_l = b.Split(':')[1].Split('|');
                        string[] rst_split = rst.Trim().Split('|');

                        if (double.Parse(snr_rssi_h[0]) >= double.Parse(rst_split[0]) &&
                            double.Parse(snr_rssi_l[0]) <= double.Parse(rst_split[0]) &&
                            double.Parse(snr_rssi_h[1]) >= double.Parse(rst_split[1]) &&
                            double.Parse(snr_rssi_l[1]) <= double.Parse(rst_split[1])

                            ) return "pass";

                    }
                    return "fail";
                    break;
                case "num":
                    {
                        double m;
                        bool z = double.TryParse(rst, out m);
                        if (z)
                        {

                            c = "'" + rst;
                            if (m <= double.Parse(a) && m >= double.Parse(b))
                            {

                                return "pass";
                            }
                            else
                            {


                                return "fail";
                            }
                        }
                    }
                    return "fail";
                    break;
                case "hex":
                    {
                        ulong m;
                        m = ulong.Parse(limitstr_group[1], System.Globalization.NumberStyles.HexNumber);

                        if (m <= ulong.Parse(a, System.Globalization.NumberStyles.HexNumber) && m >= ulong.Parse(b, System.Globalization.NumberStyles.HexNumber))
                        {

                            return "pass";
                        }
                        else
                        {


                            return "fail";
                        }


                    }
                    return "fail";
                    break;
                default:
                    {
                        c = rst;
                        if (rst.IndexOf(a) >= 0)
                        {
                            return "pass";
                        }
                        else
                        {
                            return "fail";
                        }

                    }
                    return "fail";
                    break;

            }





        }

