        string led_judger_get_led_status_together_4m(string a, string b, out string c, string d = "")
        {
            c = "";
            int[] ind;


            if (d == null) { c = "parameter can not be empty"; return "fail"; }

            if (a.Split(";".ToArray()).Length != d.Split("%".ToArray()).Length
                || b.Split(";".ToArray()).Length != d.Split("%".ToArray()).Length
                ) { c = "parameter set error"; return "fail"; }
            if (ledassyer4.get_status_together(d, out ind) == 1)
            {


                string[] str_hlimits = a.Split(";".ToArray());
                string[] str_llimits = b.Split(";".ToArray());

                for (int led_comp = 0; led_comp < ind.Length; led_comp++)
                {

                    c = c + ind[led_comp] + " | ";
                }


                bool judge = false;
                for (int led_comp = 0; led_comp < ind.Length; led_comp++)
                {


                    if (!(int.Parse(str_hlimits[led_comp]) >= ind[led_comp]) || !(int.Parse(str_llimits[led_comp]) <= ind[led_comp]))
                    {

                        return "fail";
                    }



                }

                return "pass";








            }
            else
            {


                c = "result is error"; return "fail";

            };



        }
