        string legrand_project_test_api(string a, string b, out string c, string d = "")
        {
            c = "";
            string[] testcase_str = d.Split("&".ToArray());
            if (testcase_str.Length != 2)
            {

                c = "set1_error";
                return "fail";

            }

            switch (testcase_str[0])
            {
                #region //// legrand
                case "legrand_project_set_port":
                    {
                        c = "set_port_error";

                        string[] canshus = (testcase_str[1]).Split(";".ToArray());
                        if (canshus.Length != 2)
                        {
                            c = "set2_error";
                            return "fail";
                        }

                        int rsu = legrand_obj.set_port(canshus[0], int.Parse(canshus[1]));

                        if (rsu == 1)
                        {
                            c = "pass"; return "pass";
                        }
                        else
                        {

                            c = rsu + ""; return "fail";
                        }

                    }

                    break;
                case "legrand_project_read_pin_status":
                    {
                        c = "read_pin_status_error";
                        string canshu = testcase_str[1];

                        if (canshu.IndexOf('P') < 0)
                        {
                            c = "set2_error";
                            return "fail";
                        }
                        int outlogic = -1;
                        int rsu = legrand_obj.read_pin_status(canshu, out outlogic);

                        if (rsu == 1)
                        {
                            if (a.Trim() == outlogic.ToString())
                            {

                                c = outlogic.ToString() + ""; return "pass";
                            }
                            else
                            {


                                c = outlogic.ToString() + ""; return "fail";
                            }

                        }
                        else
                        {

                            c = rsu + ""; return "fail";
                        }


                    }
                    return "fail";
                    break;
                case "legrand_project_read_AD_pin_status":
                    {
                        c = "AD_pin_status_error";
                        string canshu = testcase_str[1];
                        if (canshu.IndexOf('P') < 0)
                        {
                            c = "set2_error";
                            return "fail";
                        }
                        int advalue = -1;
                        int rsu = legrand_obj.read_ad_port(canshu, out advalue);

                        if (rsu == 1)
                        {
                            if (int.Parse(a.Trim()) >= advalue && int.Parse(b.Trim()) <= advalue)
                            {

                                c = advalue + ""; return "pass";
                            }
                            else
                            {


                                c = advalue + ""; return "fail";
                            }

                        }
                        else
                        {

                            c = rsu + ""; return "fail";
                        }


                    }
                    return "fail";
                    break;
                case "legrand_fw_update":
                    {
                        string updateexe_path = "";
                        string hexstr = "";
                        string[] setinis = testcase_str[1].Split(";".ToArray());
                        if (setinis.Length <= 1)
                        {

                            updateexe_path = @"STVP_CmdLine.exe";
                            hexstr = "SurgeBoardTest.hex";
                        }
                        else
                        {
                            updateexe_path = setinis[0];
                            hexstr = setinis[1];

                        }



                        Process fw_process = new Process();
                        ProcessStartInfo startInfo = new ProcessStartInfo(updateexe_path);
                        startInfo.Arguments = $"-no_loop -BoardName=ST-LINK  -ProgMode=SWIM  -Device={(((setinis.Length) == 3) ? "STM8S003K3" : "STM8S003F3")} -ProgMode=SWIM  -verif -FileProg={hexstr} -log";
                        startInfo.WindowStyle = ProcessWindowStyle.Hidden;
                        startInfo.CreateNoWindow = true;
                        startInfo.UseShellExecute = false; //不使用系统外壳程序启动
                        startInfo.RedirectStandardInput = true; //重定向输入（一定是true）
                        startInfo.RedirectStandardOutput = true; //重定向输出
                        startInfo.RedirectStandardError = true;

                        fw_process.StartInfo = startInfo;

                        fw_process.Start();

                        //// mylib.utility_func.ex_exe_run(@"D:\STMicroelectronics\st_toolset\stvp\legrandfwupdate.exe");
                        // System.Threading.Thread.Sleep(3000);
                        // // string g=  File.ReadAllText(@"D:\STMicroelectronics\st_toolset\stvp\Result.log");
                        // char[] buf = new char[1024];
                        // process1.StandardOutput.Read(buf, 0, 1024);

                        // string z = new string(buf);


                        StringBuilder mt = new StringBuilder();
                        do
                        {
                            mt.AppendLine(fw_process.StandardOutput.ReadLine());

                        } while (!fw_process.StandardOutput.EndOfStream);

                        fw_process.Refresh();
                        fw_process.Dispose();
                        string z = mt.ToString();

                        Regex rex = new Regex("(succeeds)", RegexOptions.IgnoreCase);
                        MatchCollection matchs = rex.Matches(z);

                        if (matchs.Count < 4) return "fail";

                        c = "pass";
                        return "pass";
                    }

                    return "fail";
                    break;
                case "read_fw_ver":
                    {
                        string canshu = testcase_str[1];

                        string tm = legrand_obj.version;

                        c = tm.Length == 0 ? "read_error" : tm;

                        if (tm == a.Trim())
                        {
                            return "pass";
                        }
                        else
                        {

                            return "fail";
                        }

                    }

                    return "fail";
                    break;


                default:
                    {

                        return "fail";
                    }
                    break;

                    #endregion ////结束 蓝牙API


                    return "fail";

            }


        }







