        string ampd_read_14_units(string a, string b, out string c, string d = "")
        {
            c = "fail";
            string judge = "fail";
            float[] rs = ampd_bms.read_voltage_14();
            double[] sph = { double.Parse(a.Split(";".ToArray())[0]), double.Parse(a.Split(";".ToArray())[1]) };
            double[] spl = { double.Parse(b.Split(";".ToArray())[0]), double.Parse(b.Split(";".ToArray())[1]) };
            float daltelim = (float)sph[0];

            for (int i = 1; i < 3; i++)
            {
                c = "";
                this.temp_board_read_max = rs.Max();
                this.temp_board_read_min = rs.Min();
                c = "" + rs.Max() + ";" + rs.Min();
                for (int i2 = 0; i2 < rs.Length; i2++)
                {
                    ampd_voltage_buf[i] = rs[i];
                    c = c + ":" + rs[i];
                }
                if (Math.Abs(rs.Min() - rs.Max()) <= daltelim && rs.Min() >= spl[1] && rs.Max() <= sph[1]) { judge = "pass"; break; }
                else { judge = "fail"; }

            }

            return judge;

        }


