        private void Process1_ErrorDataReceived(object sender, DataReceivedEventArgs e)
        {
            string m = e.Data;

            // m = null;
            if (m == null) return;
            if (m.IndexOf("0 total sweeps completed") >= 0) { diecount++; }
            if (diecount > 30 && killflog == 0)
            {
                diecount = 0;
                killflog = 1;
                //  killproc("hackrf_sweep");
