        string myrelay_set(string a, string b, out string c, string d = "@111111111111111111111111111@")
        {


            if (d.StartsWith("#") && d.EndsWith("#"))
            {
                UInt32 relay = relayself.get_relay_rec;

                string bufp = d.Replace("#", "");
                string[] getgroups = bufp.Split(";".ToCharArray());
                foreach (var strrelay in getgroups)
                {
                    string[] bufrelay_sw = strrelay.Split(":".ToCharArray());
                    string[] relay_num_group = bufrelay_sw[0].Split(",".ToCharArray());
                    foreach (var relay_num in relay_num_group)
                    {
                        int relay_number = int.Parse(relay_num);
                        int relay_sw = int.Parse(bufrelay_sw[1]);
                        if (relay_sw == 1)
                        {
                            relay = (uint)(relay & ~(1 << (relay_number - 1)));

                        }
                        else
                        {
                            relay |= (1u << (relay_number - 1));


                        }


                    }



                }
                relayself.set_rly("@" + Convert.ToString(relay, 2).PadLeft(27, '0') + "@");
                c = "pass";
                return "pass";
            }







            c = "pass";
            string judge = "pass";
            relayself.set_rly(d.Trim());

            return judge;

        }

