        /// <summary>
        /// 恒流充电法测大电容 (I=C*ΔU/Δt)
        /// 适用于 DM3058 电容档量程不够的大电容(如 0.4F 超级电容)
        /// 外部提供恒流源，函数负责精准测电压和计时
        ///
        /// d 参数字符串: "恒流值_A;目标ΔU_V;采样间隔_ms;超时_s"
        ///   默认: "0.05;2.5;100;60"  (50mA, 2.5V窗口, 100ms采样, 60s超时)
        ///
        /// a: 电容上限(F)  b: 电容下限(F)  c: 实测电容值(F)
        /// </summary>
        string dm3058_read_big_cap_by_cc(string a, string b, out string c, string d)
        {

            c = "";
            string judge = "fail";

            // 解析 d 参数，设置默认值
            if (string.IsNullOrEmpty(d)) d = "0.05;2.5;100;60";
            string[] p = d.Split(';');
            if (p.Length < 4)
            {
                c = "param_error";
                return "fail";
            }

            double constant_current;
            double delta_u_target;
            int sample_interval;
            int timeout_sec;

            try
            {
                constant_current = double.Parse(p[0]);   // 恒流值 (A)
                delta_u_target = double.Parse(p[1]);      // 目标电压上升 (V)
                sample_interval = int.Parse(p[2]);        // 采样间隔 (ms)
                timeout_sec = int.Parse(p[3]);            // 超时 (s)
            }
            catch
            {
                c = "param_error";
                return "fail";
            }

            // 1. 读初始电压 V_start
            double v_start;
            try
            {
                string ret = dm3058.dm3058_dc_read_20v();
                v_start = double.Parse(ret.Trim());
            }
            catch (Exception)
            {
                c = "eque_error";
                return "fail";
            }

            double v_target = v_start + delta_u_target;
            double v_cur = v_start;
            int fail_count = 0;

            // 2. 启动 Stopwatch，开始累积计时
            //    此后所有读数时间、通讯延迟都自动包含在内
            Stopwatch stopwatch = new Stopwatch();
            stopwatch.Start();

            do
            {
                // 采样间隔等待
                System.Threading.Thread.Sleep(sample_interval);

                try
                {
                    string ret = dm3058.dm3058_dc_read_20v();
                    v_cur = double.Parse(ret.Trim());

                    // 电压有效更新，重置失败计数
                    fail_count = 0;

                    // 检查是否达到目标电压
                    if (v_cur >= v_target)
                    {
                        stopwatch.Stop();
                        double elapsed_seconds = stopwatch.Elapsed.TotalSeconds;
                        double capacitance = constant_current * elapsed_seconds / (v_cur - v_start);

                        if (capacitance >= double.Parse(b) && capacitance <= double.Parse(a))
                        {
                            judge = "pass";
                        }
                        else
                        {
                            judge = "fail";
                        }

                        c = capacitance + "";
                        return judge;
                    }
                }
                catch (Exception)
                {
                    // 单次读电压失败，重试
                    fail_count++;
                    if (fail_count > 3)
                    {
                        stopwatch.Stop();
                        c = "eque_error";
                        return "fail";
                    }
                    continue;
                }

                // 3. 超时保护
                if (stopwatch.Elapsed.TotalSeconds > timeout_sec)
                {
                    stopwatch.Stop();
                    double elapsed_seconds = stopwatch.Elapsed.TotalSeconds;
                    // 用当前电压算一个近似值用于输出
                    double capacitance_approx = constant_current * elapsed_seconds / Math.Max(v_cur - v_start, 0.0001);
                    c = "timeout:" + capacitance_approx;
                    return "fail";
                }

            } while (true);

        }

        string md3058_read_resistance(string a, string b, out string c, string d)
        {

            c = "";
            string ret;
            string judge = "";
            float rt;
            int count = 0;
            do
            {

                try
                {
                    ret = dm3058.read_resistance();
                    rt = float.Parse(ret.Trim());



                }
