        string commline_read_delay_reg_string(string a, string b, out string c, string d)
        {

            c = "fail";
            if (commandline.IsOpen == false) commandline.Open();
            string[] commandstr = a.Split(";".ToArray());
            commandline.ReadExisting();
            if (commandstr.Length < 2 && (commandstr[0] == "0" || commandstr[0] == "1")) { c = "set_error"; return "fail"; }
            callbackdebuginfo("sender:" + commandstr[1].Trim().Replace("\n", "").Replace("\r", ""));
            if (commandstr[0] == "1")
            {

                commandline.Write(commandstr[1] + "\n");
            }
            else
            {

                commandline.Write(commandstr[1]);
            }

            for (int i = 0; i < 3; i++)
            {
                System.Threading.Thread.Sleep(100);
                if (d == null) d = "5000;" + "continue";
                string[] psr = d.Split(";".ToArray());
                string findstr = psr[1].Replace("\\n", "\r\n").Replace("[", @"\[").Replace("]", @"\]").Replace("\t", "");
                int dely = int.Parse(psr[0]);
                System.Threading.Thread.Sleep(dely);
                string rsu0 = commandline.ReadExisting();
                string rsu = rsu0.Replace("\t", "");
                callbackdebuginfo("recive: " + rsu0);
                if (utility_func.findstr_regex($"({findstr})", rsu) != "null") { c = "pass"; return "pass"; }
                else
                {
                    continue;
                };

            }
            return "fail";
        }

