                }


                if (count2 == 1)
                {


                    c = "" + matchs[dutnum].Groups[1].Value + matchs[dutnum].Groups[3].Value + "-->" + matchs[dutnum].Groups[2].Value;
                    btdogmac = matchs[dutnum].Groups[1].Value + matchs[dutnum].Groups[3].Value;
