                            }
                            else
                            {


                                relay_25_32 = (byte)(relay_25_32 & ~(1 << (relay_number - 25)));

                            }
                        }


                    }

                }
                skry1.set_relay_kbca132s(relay_1_8, relay_9_16, relay_17_24, relay_25_32);
                c = "pass";
                return "pass";

            }

            c = "set_error";
            return "fail";
        }

