        string relay_delay_set(string a, string b, out string c, string d)
        {

            if (d == null || d == "")
            {

                d = "1;00;00";
            }

            Task.Factory.StartNew(() =>
            {
                string temp = "";
                System.Threading.Thread.Sleep(int.Parse(a.Trim()));



                if (d.Trim().Substring(0, 1) == "1")
                {

                    relay_set("pass", "pass", out temp, d.Trim().Substring(2));
                }
                else if (d.Trim().Substring(0, 1) == "2")
                {
                    relay2_set("pass", "pass", out temp, d.Trim().Substring(2));

                }
                else
                {

                    relay3_set("pass", "pass", out temp, d.Trim().Substring(2));
                };

            });


            c = "pass";
            return "pass";
        }


        string relay_loop_set(string a, string b, out string c, string d)
        {

            if (d == null || d == "")
            {

                d = "1;00;00;00;00;3";
            }


            for (int lop = 0; lop < int.Parse(d.Trim().Substring(14, 1)); lop++)
            {


                switch (d.Trim().Substring(0, 1))
                {

                    case "1":
                        relay_set("pass", "pass", out temp, d.Trim().Substring(2, 5));
                        System.Threading.Thread.Sleep(int.Parse(a.Trim()));
                        relay_set("pass", "pass", out temp, d.Trim().Substring(8, 5));
                        System.Threading.Thread.Sleep(int.Parse(a.Trim()));
                        break;
                    case "2":
                        relay2_set("pass", "pass", out temp, d.Trim().Substring(2, 5));
                        System.Threading.Thread.Sleep(int.Parse(a.Trim()));
                        relay2_set("pass", "pass", out temp, d.Trim().Substring(8, 5));
                        System.Threading.Thread.Sleep(int.Parse(a.Trim()));
                        break;
                    case "3":
                        relay3_set("pass", "pass", out temp, d.Trim().Substring(2, 5));
