        public string getmac_addr()
        {

            UInt64 mac_from_ini = 0;
            string getmacstr = setup_ini_data["setproduct"]["MACADDR"];
            UInt64[] MACGROUP = { Convert.ToUInt64(getmacstr.Split(";".ToCharArray())[0], 16), Convert.ToUInt64(getmacstr.Split(";".ToCharArray())[1], 16) };
            if (MACGROUP[1] - MACGROUP[0] <= 0)
            {

                return "null";
            }
            else
            {

                mac_from_ini = Convert.ToUInt64(getmacstr.Split(";".ToCharArray())[0], 16) + 1;

                string writeback_to_ini = $"{mac_from_ini:x}".PadLeft(12, '0') + ";" + getmacstr.Split(";".ToCharArray())[1];
                SendMessage(ptrWnd, WM_SENDMACSAVE, IntPtr.Zero, writeback_to_ini);
                System.Threading.Thread.Sleep(5);
                if (writeback_to_ini != setup_ini_data["setproduct"]["MACADDR"]) return "null";
            }
            return $"{mac_from_ini:x}".PadLeft(12, '0');








        }


